mapper.select:
SELECT menu_id
FROM tb_menu
WHERE tenant_id = #{tenantId}
  AND menu_code = #{menuCode}
LIMIT 1

mapper.update:
UPDATE tb_screen_review
SET review_status    = #{status}
  , reviewer_emp_id  = #{empId}
  , review_date      = CAST(#{reviewDate} AS date)
  , request_date     = CAST(#{requestDate, jdbcType=VARCHAR} AS date)


  , developer_name     = NULL
  , dev_completed_date = NULL

  , updated_at       = now()
  , updated_by       = #{empId}
WHERE review_id = #{reviewId}

mapper.select:
SELECT COALESCE(MAX(request_no), 0) + 1
FROM tb_screen_review_history
WHERE review_id = #{reviewId}

SELECT
    draft_id                                     AS "draftId"
  , review_comment                               AS "reviewComment"
  , TO_CHAR(updated_at, 'YYYY-MM-DD HH24:MI:SS') AS "updatedAt"
FROM tb_screen_review_draft
WHERE tenant_id = #{tenantId}
  AND menu_id = #{menuId}
  AND writer_emp_id = #{empId}

mapper.delete:
DELETE FROM tb_screen_review_draft
WHERE tenant_id = #{tenantId}
  AND draft_id = #{draftId}

mapper.update:
UPDATE tb_common_file
SET owner_type = 'SCREEN_REVIEW'
  , owner_id   = #{historyId}
  , updated_at = now()
WHERE tenant_id = #{tenantId}
  AND owner_type = 'SCREEN_REVIEW_DRAFT'
  AND owner_id = #{draftId}
  AND deleted_yn = 'N'
